// Chunk splits s into chunks of at most n elements each.
func Chunk[T any](s []T, n int) [][]T {
	if n < 1 {
		return nil
	}
	var out [][]T
	for i := 0; i < len(s); i += n {
		end := i + n
		if end > len(s) {
			end = len(s)
		}
		out = append(out, s[i:end])
	}
	return out
}

