// Merge combines overlapping intervals and returns them sorted by start.
func Merge(in [][2]int) [][2]int {
	sort.Slice(in, func(i, j int) bool { return in[i][0] < in[j][0] })
	var out [][2]int
	for _, i := range in {
		if len(out) == 0 || out[len(out)-1][1] < i[0] {
			out = append(out, i)
		} else {
			out[len(out)-1][1] = max(out[len(out)-1][1], i[1])
		}
	}
	return out
}

