// RomanToInt converts a Roman numeral to an integer, handling subtractive pairs.
func RomanToInt(s string) int {
    var total int
    var prev int
    for i := len(s) - 1; i >= 0; i-- {
        switch s[i] {
        case 'I':
            if prev > 1 {
                total -= 1
            } else {
                total += 1
            }
        case 'V':
            if prev > 5 {
                total -= 5
            } else {
                total += 5
            }
        case 'X':
            if prev > 10 {
                total -= 10
            } else {
                total += 10
            }
        case 'L':
            if prev > 50 {
                total -= 50
            } else {
                total += 50
            }
        case 'C':
            if prev > 100 {
                total -= 100
            } else {
                total += 100
            }
        case 'D':
            if prev > 500 {
                total -= 500
            } else {
                total += 500
            }
        case 'M':
            if prev > 1000 {
                total -= 1000
            } else {
                total += 1000
            }
        }
        prev = total
    }
    return total
}

