// Decode expands a run-length encoding like "a3b2c1" into "aaabbc".
func Decode(s string) string {
	var out []byte
	var count int
	for i := 0; i < len(s); i++ {
		if s[i] >= '0' && s[i] <= '9' {
			count = count*10 + int(s[i]-'0')
			continue
		}
		out = append(out, bytes.Repeat([]byte{s[i]}, count)...)
		count = 1
	}
	return string(out)
}

func main() {
