// LowerBound returns the index of the first element in the sorted slice s that is
// greater than or equal to target. If none, it returns the length of s.
func LowerBound(s []int, target int) int {
	lo, hi := 0, len(s)-1
	for lo <= hi {
		mid := int(uint(lo+hi) >> 1) // avoids overflow
		switch {
		case s[mid] < target:
			lo = mid + 1
		case s[mid] > target:
			hi = mid - 1
		default:
			return mid
		}
	}
	return hi + 1
}

