// CountUntil counts how many integers are received from ch until ctx is cancelled or ch is closed.
func CountUntil(ctx context.Context, ch <-chan int) int {
	select {
	case <-ctx.Done():
		return 0
	case v, ok := <-ch:
		if !ok {
			return 0 // channel closed
		}
		return 1 + CountUntil(ctx, ch)
	}
}

func main() {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	ch := make(chan int)
	go func() { for i := 0; i < 5; i++ { ch <- i } }() // simulate a producer
	fmt.Println(CountUntil(ctx, ch)) // 5
}

